This sample shows how to use the date/time features that were introduced in SQL Server 2008. The sample uses the four new date and time types (date, time, datetime2, and datetimeoffset) to execute commands with parameters and retrieve rowset results.
This sample requires the AdventureWorks sample database, which you can download from the Microsoft SQL Server Samples and Community Projects home page.
| Security Note |
|---|
When possible, use Windows Authentication. If Windows Authentication is not available, prompt users to enter their credentials at run time. Avoid storing credentials in a file. If you must persist credentials, you should encrypt them with the Win32 crypto API. |
Example
The first (Transact-SQL) code listing creates a stored procedure used by the sample.
Compile with ole32.lib oleaut32.lib and execute the second (C++) code listing. This application connects to your computer's default SQL Server instance. On some Windows operating systems, you will need to change (localhost) or (local) to the name of your SQL Server instance. To connect to a named instance, change the connection string from L"(local)" to L"(local)\\name" , where name is the named instance. By default, SQL Server Express installs to a named instance. Make sure your INCLUDE environment variable includes the directory that contains sqlncli.h.
The third (Transact-SQL) code listing deletes the stored procedure used by the sample.
CREATE PROCEDURE sp_datetimetypes
@date_param DATE OUTPUT,
@time_param TIME(7) OUTPUT,
@datetime2_param DATETIME2(7) OUTPUT,
@datetimeoffset_param DATETIMEOFFSET(7) OUTPUT
AS
SELECT @date_param, @time_param, @datetime2_param, @datetimeoffset_param
GO
// compile with: ole32.lib oleaut32.lib
#define WIN32_LEAN_AND_MEAN
#include <stdio.h>
#include <tchar.h>
#include <sqlncli.h>
#include "oledberr.h"
#include <stddef.h>
static const DBLENGTH sc_cchStrLen = 64;
struct DateTimeTypeEx {
DBSTATUS status;
DBLENGTH length;
union {
DBTIMESTAMP ts;
DBDATE d;
DBTIME2 t;
DBTIMESTAMPOFFSET tso;
WCHAR wstr[sc_cchStrLen];
CHAR str[sc_cchStrLen];
};
};
struct TypePrecScalEx {
DBTYPE wType;
BYTE bPrec;
BYTE bScale;
WCHAR wszTypeName[64];
DBLENGTH ulSize;
};
HRESULT InitializeAndEstablishConnection (IUnknown ** ppUnkDBInitialize) {
HRESULT hr = S_OK;
IDBProperties * pIDBProperties = NULL;
IDBInitialize * pIDBInitialize = NULL;
DBPROPSET rgInitPropSet[1] = {0};
DBPROP InitProperties[4] = {0};
*ppUnkDBInitialize = NULL;
// Initialize the COM library.
CoInitialize(NULL);
// Obtain access to the SQL Server Native Client OLE DB provider.
hr = CoCreateInstance(CLSID_SQLNCLI11, NULL, CLSCTX_INPROC_SERVER, IID_IDBInitialize, (void **) &pIDBInitialize);
// Initialize property values needed to establish connection.
for (unsigned int i = 0 ; i < 4 ; i++)
VariantInit(&InitProperties[i].vValue);
// Server name.
// See DBPROP structure for more information on InitProperties
InitProperties[0].dwPropertyID = DBPROP_INIT_DATASOURCE;
InitProperties[0].vValue.vt = VT_BSTR;
InitProperties[0].vValue.bstrVal= SysAllocString(L"localhost");
InitProperties[0].dwOptions = DBPROPOPTIONS_REQUIRED;
InitProperties[0].colid = DB_NULLID;
// Database.
InitProperties[1].dwPropertyID = DBPROP_INIT_CATALOG;
InitProperties[1].vValue.vt = VT_BSTR;
InitProperties[1].vValue.bstrVal = SysAllocString(L"AdventureWorks");
InitProperties[1].dwOptions = DBPROPOPTIONS_REQUIRED;
InitProperties[1].colid = DB_NULLID;
// Username (login).
InitProperties[2].dwPropertyID = DBPROP_AUTH_INTEGRATED;
InitProperties[2].vValue.vt = VT_BSTR;
InitProperties[2].vValue.bstrVal = SysAllocString(L"SSPI");
InitProperties[2].dwOptions = DBPROPOPTIONS_REQUIRED;
InitProperties[2].colid = DB_NULLID;
InitProperties[3].dwOptions = DBPROPOPTIONS_REQUIRED;
InitProperties[3].colid = DB_NULLID;
// Construct the DBPROPSET structure(rgInitPropSet). The DBPROPSET structure is used to pass
// an array of DBPROP structures (InitProperties) to the SetProperties method.
rgInitPropSet[0].guidPropertySet = DBPROPSET_DBINIT;
rgInitPropSet[0].cProperties = 4;
rgInitPropSet[0].rgProperties = InitProperties;
// Set initialization properties.
hr = pIDBInitialize->QueryInterface(IID_IDBProperties, (void **)&pIDBProperties);
hr = pIDBProperties->SetProperties(1, rgInitPropSet);
pIDBProperties->Release();
// Establish the connection to the data source.
hr = pIDBInitialize->Initialize();
if (S_OK == hr)
*ppUnkDBInitialize = pIDBInitialize;
return hr;
}
